        ERMResidualStatisticsAddRMS_PER_COORDINATE_KM(builder, self.RMS_PER_COORDINATE_KM)
        if self.RMS_RTN_KM is not None:
            ERMResidualStatisticsAddRMS_RTN_KM(builder, RMS_RTN_KM)
        if self.MEAN_RTN_KM is not None:
            ERMResidualStatisticsAddMEAN_RTN_KM(builder, MEAN_RTN_KM)
        ERMResidualStatisticsAddMAX_3D_KM(builder, self.MAX_3D_KM)
        if self.MAX_AT is not None:
            ERMResidualStatisticsAddMAX_AT(builder, MAX_AT)
        if self.MAX_RTN_KM is not None:
            ERMResidualStatisticsAddMAX_RTN_KM(builder, MAX_RTN_KM)
        ERMResidualStatisticsAddRMS_VELOCITY_KM_S(builder, self.RMS_VELOCITY_KM_S)
        if self.SAMPLES is not None:
            ERMResidualStatisticsAddSAMPLES(builder, SAMPLES)
        ERMResidualStatistics = ERMResidualStatisticsEnd(builder)
        return ERMResidualStatistics
